import { DatabaseSync } from 'node:sqlite';

const DB_PATH = '/home/user/qwik-app/chat.db';

let db: DatabaseSync;

try {
  db = new DatabaseSync(DB_PATH);
  db.exec(`
    CREATE TABLE IF NOT EXISTS messages (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user TEXT NOT NULL,
      text TEXT NOT NULL,
      timestamp TEXT NOT NULL
    )
  `);
} catch (error) {
  console.error('Failed to initialize database:', error);
  throw error;
}

export interface Message {
  id: number;
  user: string;
  text: string;
  timestamp: string;
}

export function getAllMessages(): Message[] {
  try {
    const stmt = db.prepare('SELECT id, user, text, timestamp FROM messages ORDER BY id ASC');
    return stmt.all() as any[];
  } catch (error) {
    console.error('Failed to get messages:', error);
    return [];
  }
}

export function insertMessage(user: string, text: string): Message {
  const timestamp = new Date().toISOString();
  const stmt = db.prepare('INSERT INTO messages (user, text, timestamp) VALUES (?, ?, ?)');
  const result = stmt.run(user, text, timestamp);
  return {
    id: result.lastInsertRowid as number,
    user,
    text,
    timestamp,
  };
}

export interface SSEClient {
  id: string;
  write: (data: string) => Promise<void>;
  close: () => void;
}

const clients = new Map<string, SSEClient>();

export function addClient(client: SSEClient) {
  clients.set(client.id, client);
}

export function removeClient(id: string) {
  const client = clients.get(id);
  if (client) {
    client.close();
    clients.delete(id);
  }
}

export function broadcastMessage(message: any) {
  const data = `data: ${JSON.stringify(message)}\n\n`;
  for (const [id, client] of clients.entries()) {
    client.write(data).catch((err) => {
      console.error(`Failed to write to client ${id}, removing:`, err);
      removeClient(id);
    });
  }
}

import type { RequestHandler } from '@builder.io/qwik-city';
import { getAllMessages, insertMessage } from '~/lib/db';
import { addClient, removeClient, broadcastMessage } from '~/lib/sse';

export const onGet: RequestHandler = async ({ status, headers, getWritableStream, signal }) => {
  status(200);
  headers.set('Content-Type', 'text/event-stream');
  headers.set('Cache-Control', 'no-cache');
  headers.set('Connection', 'keep-alive');

  const writableStream = getWritableStream();
  const writer = writableStream.getWriter();
  const encoder = new TextEncoder();

  const clientId = Math.random().toString(36).substring(2);

  const client = {
    id: clientId,
    write: async (data: string) => {
      await writer.write(encoder.encode(data));
    },
    close: () => {
      writer.close().catch(() => {});
    }
  };

  addClient(client);

  // Send existing messages immediately
  try {
    const messages = getAllMessages();
    for (const msg of messages) {
      await client.write(`data: ${JSON.stringify(msg)}\n\n`);
    }
  } catch (err) {
    console.error('Error sending initial messages:', err);
    removeClient(clientId);
    return;
  }

  // Keep the connection open until aborted
  return new Promise<void>((resolve) => {
    signal.addEventListener('abort', () => {
      removeClient(clientId);
      resolve();
    });
  });
};

export const onPost: RequestHandler = async ({ parseBody, status, json }) => {
  let body: any;
  try {
    body = await parseBody();
  } catch (err) {
    status(400);
    json(400, { error: 'Invalid request body' });
    return;
  }

  if (
    !body ||
    typeof body !== 'object' ||
    typeof body.user !== 'string' ||
    typeof body.text !== 'string' ||
    body.user.trim() === '' ||
    body.text.trim() === ''
  ) {
    status(400);
    json(400, { error: 'Bad Request: "user" and "text" must be non-empty strings.' });
    return;
  }

  try {
    const savedMessage = insertMessage(body.user.trim(), body.text.trim());
    broadcastMessage(savedMessage);

    status(201);
    json(201, savedMessage);
  } catch (err) {
    console.error('Failed to save message:', err);
    status(500);
    json(500, { error: 'Internal Server Error' });
  }
};

import { component$, useStore, useSignal, useVisibleTask$, $ } from "@builder.io/qwik";
import type { DocumentHead } from "@builder.io/qwik-city";

interface Message {
  id: number;
  user: string;
  text: string;
  timestamp: string;
}

export default component$(() => {
  const state = useStore<{ messages: Message[] }>({ messages: [] });
  const userInput = useSignal("");
  const textInput = useSignal("");

  useVisibleTask$(() => {
    const eventSource = new EventSource("/api/messages");

    eventSource.onmessage = (event) => {
      try {
        const msg = JSON.parse(event.data);
        if (!state.messages.some((m) => m.id === msg.id)) {
          state.messages.push(msg);
          // Scroll to bottom on new message
          setTimeout(() => {
            const listEl = document.getElementById("message-list");
            if (listEl) {
              listEl.scrollTop = listEl.scrollHeight;
            }
          }, 50);
        }
      } catch (err) {
        console.error("Error parsing message:", err);
      }
    };

    eventSource.onerror = (err) => {
      console.error("EventSource error:", err);
    };

    return () => {
      eventSource.close();
    };
  });

  const sendMessage = $(async (e: Event) => {
    e.preventDefault();
    const user = userInput.value.trim();
    const text = textInput.value.trim();

    if (!user || !text) {
      return;
    }

    try {
      const res = await fetch("/api/messages", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ user, text }),
      });

      if (res.ok) {
        userInput.value = "";
        textInput.value = "";
      } else {
        console.error("Failed to send message:", res.statusText);
      }
    } catch (err) {
      console.error("Error sending message:", err);
    }
  });

  return (
    <div style={{ maxWidth: "600px", margin: "40px auto", padding: "20px", fontFamily: "system-ui, sans-serif" }}>
      <h2 style={{ textAlign: "center", color: "#333", marginBottom: "20px" }}>Qwik City Real-Time Chat</h2>
      <div
        id="message-list"
        data-testid="message-list"
        style={{
          border: "1px solid #ddd",
          borderRadius: "8px",
          height: "400px",
          overflowY: "auto",
          padding: "15px",
          marginBottom: "20px",
          backgroundColor: "#fafafa",
          display: "flex",
          flexDirection: "column",
          gap: "10px"
        }}
      >
        {state.messages.map((msg) => (
          <div
            key={msg.id}
            class="message-item"
            data-testid="message-item"
            style={{
              padding: "10px",
              borderRadius: "6px",
              backgroundColor: "#fff",
              boxShadow: "0 1px 2px rgba(0,0,0,0.05)",
              border: "1px solid #eaeaea"
            }}
          >
            <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "4px" }}>
              <strong style={{ color: "#0070f3" }}>{msg.user}</strong>
              <span style={{ fontSize: "0.75em", color: "#999" }}>
                {new Date(msg.timestamp).toLocaleTimeString()}
              </span>
            </div>
            <div style={{ color: "#444", wordBreak: "break-word" }}>{msg.text}</div>
          </div>
        ))}
      </div>

      <form onSubmit$={sendMessage} style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
        <div>
          <label htmlFor="user-input" style={{ display: "block", marginBottom: "6px", fontWeight: "600", color: "#555" }}>
            Username
          </label>
          <input
            id="user-input"
            data-testid="user-input"
            type="text"
            bind:value={userInput}
            placeholder="Enter your username"
            required
            style={{
              width: "100%",
              padding: "10px",
              borderRadius: "6px",
              border: "1px solid #ccc",
              fontSize: "1rem",
              boxSizing: "border-box"
            }}
          />
        </div>
        <div>
          <label htmlFor="text-input" style={{ display: "block", marginBottom: "6px", fontWeight: "600", color: "#555" }}>
            Message
          </label>
          <input
            id="text-input"
            data-testid="text-input"
            type="text"
            bind:value={textInput}
            placeholder="Type your message..."
            required
            style={{
              width: "100%",
              padding: "10px",
              borderRadius: "6px",
              border: "1px solid #ccc",
              fontSize: "1rem",
              boxSizing: "border-box"
            }}
          />
        </div>
        <button
          id="send-button"
          data-testid="send-button"
          type="submit"
          style={{
            padding: "12px",
            borderRadius: "6px",
            border: "none",
            backgroundColor: "#0070f3",
            color: "#fff",
            fontWeight: "bold",
            fontSize: "1rem",
            cursor: "pointer",
            transition: "background-color 0.2s"
          }}
        >
          Send
        </button>
      </form>
    </div>
  );
});

